PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE items (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, image TEXT DEFAULT '', created_at TEXT DEFAULT (datetime('now')), type TEXT DEFAULT '', color TEXT DEFAULT '', modifier TEXT DEFAULT '', brand TEXT DEFAULT '', size TEXT DEFAULT '', notes TEXT DEFAULT '', status TEXT DEFAULT 'owned' CHECK (status IN ('owned', 'packed', 'wishlist', 'retired')), tags TEXT DEFAULT '[]');
CREATE TABLE outfits (id TEXT PRIMARY KEY, date TEXT NOT NULL, image TEXT NOT NULL, description TEXT DEFAULT '', location TEXT DEFAULT '', created_at TEXT DEFAULT (datetime('now')), user_id TEXT DEFAULT '');
CREATE TABLE outfit_items (outfit_id TEXT NOT NULL, item_id TEXT NOT NULL, PRIMARY KEY (outfit_id, item_id));
CREATE TABLE votes (id INTEGER PRIMARY KEY AUTOINCREMENT, outfit_id TEXT NOT NULL, user_id TEXT NOT NULL, vote TEXT NOT NULL, created_at TEXT DEFAULT (datetime('now')), UNIQUE(outfit_id, user_id));
DELETE FROM sqlite_sequence;
CREATE INDEX idx_votes_outfit ON votes(outfit_id);
CREATE INDEX idx_votes_user ON votes(user_id);
CREATE INDEX idx_outfits_user ON outfits(user_id);
